using U64=uint64_t;
static U64 mix(U64 x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
struct Rng { U64 state; explicit Rng(U64 seed=42):state(seed){} U64 next(){state+=0x9e3779b97f4a7c15ULL;U64 x=state;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} double unit(){return (next()>>11)*0x1.0p-53;} U64 bounded(U64 n){if(!n)throw std::runtime_error("empty random range");return next()%n;} };
static U64 hash_bytes(const void *p,size_t n,U64 h=1469598103934665603ULL){const auto *b=static_cast<const unsigned char*>(p);while(n--)h=(h^*b++)*1099511628211ULL;return h;}
template<class T> U64 hash_vec(const std::vector<T>&v){return hash_bytes(v.data(),v.size()*sizeof(T));}
struct Stats { U64 decisions=0,neural_evaluations=0,episodes=0,correct=0,go_trials=0,go_correct=0,nogo_trials=0,nogo_correct=0,nonprobe=0,premature=0,births=0,deaths=0,replaced_deaths=0,injured_birth_replacements=0; };
struct Person { U64 id=0,parent=0,born=0,episodes=0,correct=0;float energy=48;uint8_t alive=1,task_ready=0; };
struct Task {std::array<float,8> input{};int target=0;bool probe=false,go=false;};
// Environment uses only seed, global episode, slot and channel; evolutionary RNG never changes task draws.
static Task task(U64 seed,U64 episode,U64 slot,unsigned phase){
 auto draw=[&](U64 c){return mix(seed^mix(episode+0x5000)^mix(slot+0x9000)^mix(c+0xd000));};
 bool cue=draw(0)&1,rule=draw(1)&1,go=(draw(2)&3)!=0;Task t;t.probe=phase==7;t.go=go;
 if(phase==0){t.input[cue?1:0]=1;}
 else if(t.probe){t.input[3]=1;t.input[4]=rule?1.f:-1.f;t.input[5]=go?1.f:-1.f;t.target=go?((cue^rule)?2:1):0;}
 else{t.input[2]=1;t.input[6]=((draw(8+phase)&3)==0)?1.f:0.f;t.input[7]=((draw(24+phase)&3)==0)?1.f:0.f;}
 return t;
}
struct World {
 U64 population=4096,hidden=64,seed=42,next_id=1,max_memory_mib=256;double mutation=.015,mutation_scale=.05;
 Rng rng;Stats stats;std::vector<Person> people;std::vector<float> genomes,state;std::vector<uint8_t> disabled;std::set<U64> dead;
 std::vector<U64> injured_ids;std::string lesion_kind="none";double severity=0,exposure=0;U64 lesion_seed=0;
 size_t params()const{return hidden*hidden+12*hidden+3;}size_t region()const{return std::max<U64>(1,hidden/4);}
 void validate_sizes()const{if(population<2||population>262144||hidden<4||hidden>256)throw std::runtime_error("population must be 2..262144; hidden must be 4..256");U64 required=population*(params()*sizeof(float)+hidden*(sizeof(float)+sizeof(uint8_t))+sizeof(Person)+128)+hidden*16+1024*1024; if(max_memory_mib<8||max_memory_mib>1536||required>max_memory_mib*1024*1024)throw std::runtime_error("world exceeds --max-memory-mib resource budget before allocation");}
 void init(){validate_sizes();rng=Rng(seed);people.resize(population);genomes.resize(population*params());state.assign(population*hidden,0);disabled.assign(population*hidden,0);float recurrent=1.1f/std::sqrt(float(hidden));for(U64 s=0;s<population;++s){people[s].id=next_id++;auto*w=genomes.data()+s*params();for(U64 j=0;j<hidden;++j){for(U64 k=0;k<hidden;++k)w[j*hidden+k]=float((rng.unit()*2-1)*recurrent)+(j==k?.5f:0.f);}size_t o=hidden*hidden;for(U64 j=0;j<hidden*8;++j)w[o+j]=float((rng.unit()*2-1)*.6);o+=hidden*8;for(U64 j=0;j<hidden;++j)w[o+j]=float((rng.unit()*2-1)*.15);o+=hidden;for(U64 j=0;j<3*hidden;++j)w[o+j]=float((rng.unit()*2-1)/std::sqrt(double(hidden)));o+=3*hidden;for(int j=0;j<3;++j)w[o+j]=float((rng.unit()*2-1)*.15);}}
 int action(U64 slot,const Task&t,bool reset,std::vector<float>&scratch){return evaluate(genomes.data()+slot*params(),state.data()+slot*hidden,disabled.data()+slot*hidden,t,reset,scratch);}
 int evaluate(const float*w,float*h,const uint8_t*mask,const Task&t,bool reset,std::vector<float>&scratch)const{
 if(reset)std::fill(h,h+hidden,0.f);scratch.resize(hidden);size_t io=hidden*hidden,bo=io+hidden*8,oo=bo+hidden,ob=oo+3*hidden;
 for(U64 j=0;j<hidden;++j){if(mask[j]){scratch[j]=0;continue;}float a=w[bo+j];const float*r=w+j*hidden;for(U64 k=0;k<hidden;++k)a+=r[k]*h[k];const float*i=w+io+j*8;for(unsigned k=0;k<8;++k)a+=i[k]*t.input[k];scratch[j]=std::tanh(a);}
 std::copy(scratch.begin(),scratch.end(),h);int chosen=0;float best=-std::numeric_limits<float>::infinity();for(int a=0;a<3;++a){float score=w[ob+a];for(U64 j=0;j<hidden;++j)score+=w[oo+a*hidden+j]*h[j];if(score>best){best=score;chosen=a;}}return chosen;
 }
 bool injured(U64 s)const{const auto*b=disabled.data()+s*hidden;return std::any_of(b,b+hidden,[](uint8_t x){return x!=0;});}
 void die(U64 s){if(!people[s].alive)return;people[s].alive=0;++stats.deaths;dead.insert(s);std::fill(state.begin()+s*hidden,state.begin()+(s+1)*hidden,0.f);}
 void birth(U64 parent){U64 child;if(!dead.empty()){auto it=dead.lower_bound(rng.bounded(population));if(it==dead.end())it=dead.begin();child=*it;dead.erase(it);}else{child=(parent+1+rng.bounded(population-1))%population;++stats.deaths;++stats.replaced_deaths;}
 if(injured(child))++stats.injured_birth_replacements;const U64 parent_id=people[parent].id;people[parent].energy-=36.f;Person baby;baby.id=next_id++;baby.parent=parent_id;baby.born=stats.decisions;baby.energy=32;people[child]=baby;
 const float*source=genomes.data()+parent*params();float*dest=genomes.data()+child*params();std::copy(source,source+params(),dest);for(size_t k=0;k<params();++k)if(rng.unit()<mutation)dest[k]=std::clamp(dest[k]+float((rng.unit()+rng.unit()-1)*mutation_scale),-4.f,4.f);std::fill(state.begin()+child*hidden,state.begin()+(child+1)*hidden,0.f);std::fill(disabled.begin()+child*hidden,disabled.begin()+(child+1)*hidden,uint8_t(0));++stats.births;
 }
 void step(std::vector<float>&scratch){U64 d=stats.decisions++,slot=d%population;if(!people[slot].alive)return;unsigned phase=unsigned((d/population)%8);U64 episode=d/(population*8);Task t=task(seed,episode,slot,phase);int a=action(slot,t,phase==0,scratch);++stats.neural_evaluations;auto&p=people[slot];if(phase==0)p.task_ready=1;p.energy-=.03f;if(t.probe&&p.task_ready){++stats.episodes;++p.episodes;bool correct=a==t.target;stats.correct+=correct;p.correct+=correct;if(t.go){++stats.go_trials;stats.go_correct+=correct;}else{++stats.nogo_trials;stats.nogo_correct+=correct;}p.energy+=correct?8.f:-4.f;p.task_ready=0;}else if(!t.probe){++stats.nonprobe;bool premature=a!=0;stats.premature+=premature;if(premature)p.energy-=.05f;}if(p.energy<=0)die(slot);else if(p.energy>=72)birth(slot);}
 void lesion(const std::string&kind,double dose,double fraction,U64 ls){if(kind=="none")return;if(kind!="executive"&&kind!="random")throw std::runtime_error("lesion must be none, executive or random");if(!injured_ids.empty()){if(kind==lesion_kind&&dose==severity&&fraction==exposure&&ls==lesion_seed)return;throw std::runtime_error("checkpoint already has a lesion; fork from the common baseline");}lesion_kind=kind;severity=dose;exposure=fraction;lesion_seed=ls;Rng lr(ls);std::vector<U64> slots;for(U64 s=0;s<population;++s)if(people[s].alive)slots.push_back(s);for(size_t n=slots.size();n>1;--n)std::swap(slots[n-1],slots[lr.bounded(n)]);size_t affected=std::min(slots.size(),size_t(std::llround(fraction*slots.size())));size_t units=std::min(region(),size_t(std::llround(dose*region())));for(size_t n=0;n<affected;++n){U64 s=slots[n];if(units)injured_ids.push_back(people[s].id);std::vector<U64> pool(kind=="executive"?region():hidden);std::iota(pool.begin(),pool.end(),kind=="executive"?hidden-region():0);for(size_t k=pool.size();k>1;--k)std::swap(pool[k-1],pool[lr.bounded(k)]);for(size_t k=0;k<units;++k){disabled[s*hidden+pool[k]]=1;state[s*hidden+pool[k]]=0;}}std::sort(injured_ids.begin(),injured_ids.end());}
};
static double ratio(U64 a,U64 b){return b?double(a)/double(b):0;}
static std::string json(const World&w,double elapsed=0,U64 start=0,bool detail=false){U64 alive=0,injured_alive=0,disabled_units=0,alive_disabled_units=0;double energy=0;for(U64 s=0;s<w.population;++s){if(w.people[s].alive){++alive;energy+=w.people[s].energy;injured_alive+=w.injured(s);}for(U64 j=0;j<w.hidden;++j)if(w.disabled[s*w.hidden+j]){++disabled_units;alive_disabled_units+=w.people[s].alive;}}const auto&t=w.stats;std::ostringstream o;o<<std::setprecision(12)<<"{\"type\":\"progress\",\"kind\":\"progress\",\"population\":"<<w.population<<",\"hidden\":"<<w.hidden<<",\"seed\":"<<w.seed<<",\"parameters_per_agent\":"<<w.params()<<",\"total_parameters\":"<<w.params()*w.population<<",\"payload_bytes\":"<<w.genomes.size()*4+w.state.size()*4+w.disabled.size()<<",\"decisions\":"<<t.decisions<<",\"neural_evaluations\":"<<t.neural_evaluations<<",\"start_decisions\":"<<start<<",\"episodes\":"<<t.episodes<<",\"correct\":"<<t.correct<<",\"go_trials\":"<<t.go_trials<<",\"go_correct\":"<<t.go_correct<<",\"nogo_trials\":"<<t.nogo_trials<<",\"nogo_correct\":"<<t.nogo_correct<<",\"accuracy\":"<<ratio(t.correct,t.episodes)<<",\"go_accuracy\":"<<ratio(t.go_correct,t.go_trials)<<",\"nogo_accuracy\":"<<ratio(t.nogo_correct,t.nogo_trials)<<",\"nonprobe\":"<<t.nonprobe<<",\"premature\":"<<t.premature<<",\"premature_response_rate\":"<<ratio(t.premature,t.nonprobe)<<",\"births\":"<<t.births<<",\"deaths\":"<<t.deaths<<",\"replaced_deaths\":"<<t.replaced_deaths<<",\"alive\":"<<alive<<",\"mean_energy\":"<<(alive?energy/alive:0)<<",\"injured_initial\":"<<w.injured_ids.size()<<",\"injured_alive\":"<<injured_alive<<",\"injured_birth_replacements\":"<<t.injured_birth_replacements<<",\"disabled_units\":"<<disabled_units<<",\"alive_disabled_units\":"<<alive_disabled_units<<",\"executive_units\":"<<w.region()<<",\"elapsed_seconds\":"<<elapsed<<",\"decisions_per_second\":"<<(elapsed?(t.decisions-start)/elapsed:0)<<",\"reproduction\":\"simulator_supplied_energy_threshold\",\"lesion_dose_basis\":\"fraction_of_designated_region\",\"lesion\":{\"kind\":\""<<w.lesion_kind<<"\",\"severity\":"<<w.severity<<",\"exposure\":"<<w.exposure<<",\"seed\":"<<w.lesion_seed<<"}";
 if(detail){o<<",\"rng_state\":"<<w.rng.state<<",\"next_id\":"<<w.next_id<<",\"genome_hash\":\""<<std::hex<<hash_vec(w.genomes)<<"\",\"state_hash\":\""<<hash_vec(w.state)<<"\",\"mask_hash\":\""<<hash_vec(w.disabled)<<"\""<<std::dec<<",\"injured_ids\":[";for(size_t k=0;k<w.injured_ids.size();++k){if(k)o<<",";o<<w.injured_ids[k];}o<<"],\"individuals\":[";for(U64 s=0;s<w.population;++s){if(s)o<<",";const auto&p=w.people[s];o<<"{\"slot\":"<<s<<",\"id\":"<<p.id<<",\"parent\":"<<p.parent<<",\"born\":"<<p.born<<",\"alive\":"<<unsigned(p.alive)<<",\"energy\":"<<p.energy<<",\"injured\":"<<(w.injured(s)?"true":"false")<<",\"episodes\":"<<p.episodes<<",\"correct\":"<<p.correct<<"}";}o<<"]";}
 o<<"}";return o.str();}
struct Writer {std::ofstream f;U64 hash=1469598103934665603ULL;explicit Writer(const std::string&p):f(p,std::ios::binary){if(!f)throw std::runtime_error("cannot write "+p);}void bytes(const void*p,size_t n){f.write(static_cast<const char*>(p),n);hash=hash_bytes(p,n,hash);if(!f)throw std::runtime_error("checkpoint write failed");}template<class T>void put(const T&x){bytes(&x,sizeof(x));}template<class T>void vec(const std::vector<T>&v){bytes(v.data(),v.size()*sizeof(T));}};
struct Reader {std::ifstream f;U64 hash=1469598103934665603ULL;explicit Reader(const std::string&p):f(p,std::ios::binary){if(!f)throw std::runtime_error("cannot read "+p);}void bytes(void*p,size_t n){f.read(static_cast<char*>(p),n);if(!f)throw std::runtime_error("truncated checkpoint");hash=hash_bytes(p,n,hash);}template<class T>void get(T&x){bytes(&x,sizeof(x));}template<class T>void vec(std::vector<T>&v){bytes(v.data(),v.size()*sizeof(T));}};
static void save(const World&w,const std::string&path){const std::string temporary=path+".tmp."+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());Writer b(temporary);const char magic[8]={'N','E','U','R','A','L','0','2'};b.bytes(magic,8);b.put(w.population);b.put(w.hidden);b.put(w.seed);b.put(w.next_id);b.put(w.mutation);b.put(w.mutation_scale);b.put(w.rng.state);b.put(w.stats);U64 kind=w.lesion_kind=="none"?0:w.lesion_kind=="executive"?1:2;b.put(kind);b.put(w.severity);b.put(w.exposure);b.put(w.lesion_seed);U64 n=w.injured_ids.size();b.put(n);b.vec(w.injured_ids);for(const auto&p:w.people){b.put(p.id);b.put(p.parent);b.put(p.born);b.put(p.episodes);b.put(p.correct);b.put(p.energy);b.put(p.alive);b.put(p.task_ready);}b.vec(w.genomes);b.vec(w.state);b.vec(w.disabled);U64 h=b.hash;b.f.write(reinterpret_cast<const char*>(&h),sizeof(h));b.f.flush();if(!b.f)throw std::runtime_error("checkpoint finalize failed");b.f.close();if(std::rename(temporary.c_str(),path.c_str())!=0){std::remove(temporary.c_str());throw std::runtime_error("atomic checkpoint rename failed");}}
static World load(const std::string&path,U64 memory_mib=256){Reader b(path);char magic[8];b.bytes(magic,8);if(std::memcmp(magic,"NEURAL02",8))throw std::runtime_error("unsupported checkpoint");World w;w.max_memory_mib=memory_mib;b.get(w.population);b.get(w.hidden);w.validate_sizes();b.get(w.seed);b.get(w.next_id);b.get(w.mutation);b.get(w.mutation_scale);b.get(w.rng.state);b.get(w.stats);U64 kind;b.get(kind);if(kind>2)throw std::runtime_error("invalid lesion kind");w.lesion_kind=kind==0?"none":kind==1?"executive":"random";b.get(w.severity);b.get(w.exposure);b.get(w.lesion_seed);U64 n;b.get(n);if(n>w.population)throw std::runtime_error("invalid injured IDs");w.injured_ids.resize(n);b.vec(w.injured_ids);w.people.resize(w.population);for(U64 s=0;s<w.population;++s){auto&p=w.people[s];b.get(p.id);b.get(p.parent);b.get(p.born);b.get(p.episodes);b.get(p.correct);b.get(p.energy);b.get(p.alive);b.get(p.task_ready);if(!p.id||p.id>=w.next_id||p.alive>1||p.task_ready>1||!std::isfinite(p.energy))throw std::runtime_error("invalid individual");if(!p.alive)w.dead.insert(s);}w.genomes.resize(w.population*w.params());w.state.resize(w.population*w.hidden);w.disabled.resize(w.population*w.hidden);b.vec(w.genomes);b.vec(w.state);b.vec(w.disabled);U64 expected;b.f.read(reinterpret_cast<char*>(&expected),sizeof(expected));if(!b.f||expected!=b.hash||b.f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("checkpoint checksum/length mismatch");for(float x:w.genomes)if(!std::isfinite(x))throw std::runtime_error("nonfinite genome");for(size_t k=0;k<w.state.size();++k)if(!std::isfinite(w.state[k])||w.disabled[k]>1||(w.disabled[k]&&w.state[k]!=0))throw std::runtime_error("invalid working state/mask");if(!std::isfinite(w.mutation)||w.mutation<0||w.mutation>1||!std::isfinite(w.mutation_scale)||w.mutation_scale<0||!std::isfinite(w.severity)||w.severity<0||w.severity>1||!std::isfinite(w.exposure)||w.exposure<0||w.exposure>1)throw std::runtime_error("invalid checkpoint settings");return w;}
// Assays run on private recurrent state. They do not train, reproduce, change
// lesions, or advance the world's task stream or evolutionary random generator.
static std::string assay(const World&w,U64 samples,U64 trials,U64 seed,const std::string&cue_mode="normal"){
 if(cue_mode!="normal"&&cue_mode!="erased"&&cue_mode!="memory-reset")throw std::runtime_error("cue-mode must be normal, erased or memory-reset");
 if(!samples||!trials||samples>100000||trials>100000||samples*trials>10000000)throw std::runtime_error("invalid assay size");
 std::vector<U64> pool;for(U64 s=0;s<w.population;++s)if(w.people[s].alive)pool.push_back(s);
 const U64 alive_pool_count=pool.size();Rng r(seed);for(size_t n=pool.size();n>1;--n)std::swap(pool[n-1],pool[r.bounded(n)]);samples=std::min<U64>(samples,pool.size());
 Stats st;std::vector<float>h(w.hidden),scratch;std::ostringstream ids,records;ids<<"[";records<<"[";
 for(U64 s=0;s<samples;++s){
  const U64 slot=pool[s];const auto&p=w.people[slot];Stats sample;std::string correct_bits,actions,targets,go_bits;
  if(s){ids<<",";records<<",";}ids<<slot;
  for(U64 tr=0;tr<trials;++tr){
   for(unsigned phase=0;phase<8;++phase){
    Task t=task(seed,tr,slot,phase);if(cue_mode=="erased"&&phase==0)t.input.fill(0.f);
    const bool reset=phase==0||(cue_mode=="memory-reset"&&t.probe);
    int a=w.evaluate(w.genomes.data()+slot*w.params(),h.data(),w.disabled.data()+slot*w.hidden,t,reset,scratch);
    if(t.probe){
     ++sample.episodes;const bool correct=a==t.target;sample.correct+=correct;
     if(t.go){++sample.go_trials;sample.go_correct+=correct;}else{++sample.nogo_trials;sample.nogo_correct+=correct;}
     correct_bits.push_back(correct?'1':'0');actions.push_back(char('0'+a));targets.push_back(char('0'+t.target));go_bits.push_back(t.go?'1':'0');
    }
   }
  }
  st.episodes+=sample.episodes;st.correct+=sample.correct;st.go_trials+=sample.go_trials;st.go_correct+=sample.go_correct;st.nogo_trials+=sample.nogo_trials;st.nogo_correct+=sample.nogo_correct;
  U64 disabled_count=0;for(U64 j=0;j<w.hidden;++j)disabled_count+=w.disabled[slot*w.hidden+j]!=0;
  records<<std::setprecision(12)<<"{\"slot\":"<<slot<<",\"id\":"<<p.id<<",\"parent\":"<<p.parent<<",\"injured\":"<<(disabled_count?"true":"false")<<",\"disabled_count\":"<<disabled_count
   <<",\"episodes\":"<<sample.episodes<<",\"correct\":"<<sample.correct<<",\"accuracy\":"<<ratio(sample.correct,sample.episodes)<<",\"go_trials\":"<<sample.go_trials<<",\"go_correct\":"<<sample.go_correct<<",\"go_accuracy\":"<<ratio(sample.go_correct,sample.go_trials)
   <<",\"nogo_trials\":"<<sample.nogo_trials<<",\"nogo_correct\":"<<sample.nogo_correct<<",\"nogo_accuracy\":"<<ratio(sample.nogo_correct,sample.nogo_trials)<<",\"correct_per_trial\":\""<<correct_bits<<"\",\"action_per_trial\":\""<<actions<<"\",\"target_per_trial\":\""<<targets<<"\",\"go_per_trial\":\""<<go_bits<<"\"}";
 }
 ids<<"]";records<<"]";std::ostringstream o;
 o<<std::setprecision(12)<<"{\"samples\":"<<samples<<",\"trials\":"<<trials<<",\"seed\":"<<seed<<",\"episodes\":"<<st.episodes<<",\"correct\":"<<st.correct<<",\"accuracy\":"<<ratio(st.correct,st.episodes)<<",\"go_trials\":"<<st.go_trials<<",\"go_correct\":"<<st.go_correct<<",\"go_accuracy\":"<<ratio(st.go_correct,st.go_trials)<<",\"nogo_trials\":"<<st.nogo_trials<<",\"nogo_correct\":"<<st.nogo_correct<<",\"nogo_accuracy\":"<<ratio(st.nogo_correct,st.nogo_trials)
  <<",\"chance_uniform\":0.333333333333,\"always_withhold\":0.25,\"static_action\":0.375,\"frozen_weights\":true,\"cue_mode\":\""<<cue_mode<<"\",\"alive_pool_count\":"<<alive_pool_count<<",\"sample_frame\":\"alive_at_assay\",\"identity_note\":\"Same seed and unchanged alive slots produce matched samples; after evolution or death compare individual IDs as well as slots.\",\"sample_slots\":"<<ids.str()<<",\"per_sample\":"<<records.str()<<"}";
 return o.str();
}
static void selftest(){World w;w.population=4;w.hidden=8;w.mutation=0;w.init();std::vector<float>scratch;auto before=w.genomes;w.lesion("executive",1,1,7);if(w.genomes!=before)throw std::runtime_error("lesion changed genome");for(U64 s=0;s<4;++s)for(U64 j=6;j<8;++j)if(!w.disabled[s*8+j])throw std::runtime_error("lesion placement");for(int k=0;k<100;++k)w.step(scratch);for(size_t k=0;k<w.disabled.size();++k)if(w.disabled[k]&&w.state[k]!=0)throw std::runtime_error("lesion persistence");w.people[0].energy=72;U64 parentid=w.people[0].id;std::vector<float>parent(w.genomes.begin(),w.genomes.begin()+w.params());w.birth(0);U64 child=4;for(U64 s=1;s<4;++s)if(w.people[s].parent==parentid)child=s;if(child==4||w.injured(child)||w.people[child].id==parentid||!std::equal(parent.begin(),parent.end(),w.genomes.begin()+child*w.params()))throw std::runtime_error("offspring inheritance/reset");for(U64 j=0;j<8;++j)if(w.state[child*8+j]!=0)throw std::runtime_error("offspring working state");if(w.people[child].task_ready)throw std::runtime_error("newborn inherited task readiness");U64 scored=w.stats.episodes;w.stats.decisions=7*w.population+child;w.step(scratch);if(w.stats.episodes!=scored)throw std::runtime_error("uncued newborn scored");w.stats.decisions=8*w.population+child;w.step(scratch);if(!w.people[child].task_ready)throw std::runtime_error("cue readiness missing");w.stats.decisions=15*w.population+child;w.step(scratch);if(w.stats.episodes!=scored+1)throw std::runtime_error("cued newborn not scored");std::vector<uint8_t>full(8,1);std::vector<float>h(8,1);Task t=task(3,1,1,7);w.evaluate(w.genomes.data(),h.data(),full.data(),t,false,scratch);if(std::any_of(h.begin(),h.end(),[](float x){return x!=0;}))throw std::runtime_error("full lesion state");std::cout<<"neural self-test passed: inheritance, masks, state reset, genomic integrity, complete-cue scoring\n";}
struct Args{std::map<std::string,std::string>m;Args(int argc,char**argv){const std::set<std::string>allowed={"population","hidden","seed","decisions","checkpoint","metrics","progress-every","load","lesion","severity","exposure","lesion-seed","output","samples","trials","mutation","mutation-scale","max-memory-mib","cue-mode"};for(int i=2;i<argc;++i){std::string k=argv[i];if(k.rfind("--",0)!=0||i+1>=argc||!allowed.count(k.substr(2)))throw std::runtime_error("unknown/missing option "+k);k=k.substr(2);if(m.count(k))throw std::runtime_error("duplicate option "+k);m[k]=argv[++i];}}std::string str(const std::string&k,const std::string&d="")const{auto it=m.find(k);return it==m.end()?d:it->second;}U64 num(const std::string&k,U64 d)const{auto s=str(k);if(s.empty())return d;if(s[0]=='-')throw std::runtime_error("negative "+k);size_t n=0;U64 v=std::stoull(s,&n);if(n!=s.size())throw std::runtime_error("invalid "+k);return v;}double real(const std::string&k,double d)const{auto s=str(k);if(s.empty())return d;size_t n=0;double v=std::stod(s,&n);if(n!=s.size()||!std::isfinite(v))throw std::runtime_error("invalid "+k);return v;}};
static void output(const std::string&s,const std::string&path){if(path.empty())std::cout<<s<<"\n";else{std::ofstream f(path);if(!f)throw std::runtime_error("cannot write "+path);f<<s<<"\n";}}
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("use run, inspect, assay, or --self-test");std::string command=argv[1];if(command=="--self-test"){selftest();return 0;}Args a(argc,argv);if(command!="run"&&command!="inspect"&&command!="assay")throw std::runtime_error("unknown command");if(command!="assay"&&!a.str("cue-mode").empty())throw std::runtime_error("cue-mode is assay-only");World w;if(!a.str("load").empty())w=load(a.str("load"),a.num("max-memory-mib",256));else{if(command!="run")throw std::runtime_error("--load required");w.population=a.num("population",4096);w.max_memory_mib=a.num("max-memory-mib",256);w.hidden=a.num("hidden",64);w.seed=a.num("seed",42);w.mutation=a.real("mutation",.015);w.mutation_scale=a.real("mutation-scale",.05);if(w.mutation<0||w.mutation>1||w.mutation_scale<0||w.mutation_scale>4)throw std::runtime_error("invalid mutation");w.init();}if(command=="inspect"){output(json(w,0,0,true),a.str("output"));return 0;}if(command=="assay"){output(assay(w,a.num("samples",128),a.num("trials",32),a.num("seed",991),a.str("cue-mode","normal")),a.str("output"));return 0;}double dose=a.real("severity",.25),exposure=a.real("exposure",.25);if(dose<0||dose>1||exposure<0||exposure>1)throw std::runtime_error("severity and exposure must be 0..1");w.lesion(a.str("lesion","none"),dose,exposure,a.num("lesion-seed",991));std::string cp=a.str("checkpoint");if(cp.empty())throw std::runtime_error("--checkpoint required");U64 count=a.num("decisions",3000000),every=a.num("progress-every",100000);if(!every||count>std::numeric_limits<U64>::max()-w.stats.decisions)throw std::runtime_error("invalid decision/progress count");std::ofstream metrics;if(!a.str("metrics").empty()){metrics.open(a.str("metrics"));if(!metrics)throw std::runtime_error("cannot write metrics");}U64 start=w.stats.decisions;auto begin=std::chrono::steady_clock::now();auto emit=[&](){double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();auto row=json(w,elapsed,start);std::cout<<row<<std::endl;if(metrics){metrics<<row<<std::endl;}};emit();std::vector<float>scratch;for(U64 done=0;done<count;++done){w.step(scratch);if((done+1)%every==0)emit();}if(count%every||count==0)emit();save(w,cp);return 0;}catch(const std::exception&e){std::cerr<<"neural_engine: "<<e.what()<<"\n";return 1;}}
